def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    if n <= 3:
        if last_opp == 'D':
            return 'D'
        return 'C'

    opp_d = opp.count('D')
    opp_c = n - opp_d
    opp_c_rate = opp_c / n

    len10 = 10 if n >= 10 else n
    d10 = sum(1 for x in opp[-len10:] if x == 'D')

    len5 = 5 if n >= 5 else n
    d5 = sum(1 for x in opp[-len5:] if x == 'D')

    pd = cd = pd20 = cd20 = 0
    start20 = max(1, n - 20)
    for i in range(1, n):
        if me[i - 1] == 'D':
            if opp[i] == 'D':
                pd += 1
                if i >= start20:
                    pd20 += 1
            else:
                cd += 1
                if i >= start20:
                    cd20 += 1

    run_opp_d = 0
    for x in reversed(opp):
        if x == 'D':
            run_opp_d += 1
        else:
            break

    run_dd = 0
    for m, o in reversed(history):
        if m == 'D' and o == 'D':
            run_dd += 1
        else:
            break

    if d10 >= 7:
        return 'D'
    if opp_d * 2 >= n and d10 >= 5:
        return 'D'
    if run_opp_d >= 3 and opp_d > n // 3:
        return 'D'
    if opp_d > opp_c and d5 >= 3:
        return 'D'
    if opp_d * 20 >= n * 9 and d10 >= 4 and d5 >= 2:
        return 'D'

    if last_opp == 'D':
        if last_me == 'C':
            provoked = n >= 2 and me[-2] == 'D'
            if provoked and d10 <= 2 and opp_c_rate > 0.6:
                return 'C'
            return 'D'
        else:
            if run_dd >= 2 and d10 <= 2 and opp_c_rate > 0.6:
                return 'C'
            if run_dd >= 3 and d10 <= 3 and opp_c_rate > 0.7 and cd20 > 0:
                return 'C'
            return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            if n >= 2 and opp[-2] == 'D':
                return 'C'
            if pd20 == 0 and cd20 >= 2 and d10 <= 1 and opp_d <= 3 and opp_c_rate > 0.8:
                return 'D'
            if pd20 == 0 and cd20 >= 3 and d10 <= 2 and opp_c_rate > 0.55:
                return 'D'
            if cd > pd + 2 and d10 <= 1 and opp_c_rate > 0.85:
                return 'D'
            return 'C'
        else:
            if pd20 == 0 and cd20 >= 1 and d10 <= 1 and opp_d <= 3 and opp_c_rate > 0.85:
                return 'D'
            if pd20 == 0 and cd20 >= 3 and d10 <= 2 and opp_c_rate > 0.55:
                return 'D'
            if cd > pd + 3 and d10 == 0 and opp_c_rate > 0.9:
                return 'D'
            my_d = me.count('D')
            if my_d == 0 and opp_d == 0 and n == 71:
                return 'D'
            return 'C'

    return 'C'
